/**
 * Emit the strict dispatch-tool OpenAPI paths to a standalone document.
 *
 * The full client-facing document (gateway routes + these tool paths) is served
 * live at `GET /lobu/api/docs/openapi.json` and is what `@lobu/client` is
 * generated from. This script emits ONLY the tool surface — no running server or
 * database required — so the domain half of the contract can be inspected,
 * diffed, or fed to `openapi-ts` offline.
 *
 * Usage: bun packages/server/scripts/emit-openapi.ts [outfile]
 */
import { writeFileSync } from "node:fs";
import { generateStrictToolPaths } from "../src/utils/openapi-generator";

const doc = {
	openapi: "3.1.0",
	info: {
		title: "Lobu API — dispatch tools",
		version: "1.0.0",
		description:
			"Strict projection of the dispatch-tool surface (POST /api/{orgSlug}/{tool}) from the server's TypeBox schemas.",
	},
	servers: [{ url: "http://localhost:8787", description: "Local development" }],
	paths: generateStrictToolPaths(),
};

const out = process.argv[2] ?? "/dev/stdout";
writeFileSync(out, `${JSON.stringify(doc, null, 2)}\n`);
import { defineConfig } from "@hey-api/openapi-ts";

export default defineConfig({
  input:
    process.env.LOBU_OPENAPI_URL ??
    "http://localhost:8787/lobu/api/docs/openapi.json",
  output: {
    path: "src/generated",
    format: "prettier",
    importFileExtension: ".js",
  },
  plugins: ["@hey-api/typescript", "@hey-api/sdk", "@hey-api/client-fetch"],
});

	it("enumerates the valid catalog.listCatalog kinds", () => {
		// {kind: 'connector'} and {kinds: ['connector']} both failed live with
		// errors that never named the valid (plural) values.
		const list = METHOD_METADATA["catalog.listCatalog"];
		const sig = list.signature ?? "";
		expect(sig).toContain("'connectors'");
		expect(sig).toContain("'skills'");
		expect(sig).toContain("'behaviors'");
		expect(list.summary).toContain("'connectors'");
		expect(list.summary).toContain("'behaviors'");
	});

	it("documents knowledge.read's content_ids (array) arg — the shape save_memory's exact_read hint points at", () => {
		const read = METHOD_METADATA["knowledge.read"];
		expect(read.summary).toContain("content_ids");
		expect(read.example ?? "").toContain("content_ids: [");
	});

	it("documents the exact positional signature AND the accepted object form for every positional-id method", () => {
		// #2046: these methods take a positional id at runtime but were described
		// like named-object methods, so discovery and runtime disagreed. Every one
		// must now document `path(field: type)` and the `{ field }` object form the
