/**
 * ClientSDK `knowledge` namespace.
 *
 * Wraps the `search_memory`, `save_memory`, and `read_knowledge` handlers.
 * `deleteContent` is SDK-only, exposed as `client.knowledge.delete` rather
 * than as a registered MCP tool.
 */

import type { Env } from "../../index";
import { deleteContent } from "../../tools/delete_content";
import { getContent } from "../../tools/get_content";
import type { ToolContext } from "../../tools/registry";
import { saveContent } from "../../tools/save_content";
import { search } from "../../tools/search";

export interface KnowledgeSearchInput {
	query?: string;
	entity_type?: string;
	entity_id?: number;
	parent_id?: number;
	market?: string;
	category?: string;
	fuzzy?: boolean;
	min_similarity?: number;
	include_connections?: boolean;
	include_content?: boolean;
	limit?: number;
}

interface KnowledgeSaveBase {
	entity_ids?: number[];
	semantic_type: string;
	metadata?: Record<string, unknown>;
	title?: string;
	slug?: string;
	author?: string;
	payload_data?: Record<string, unknown>;
	payload_template?: Record<string, unknown>;
	attachments?: Array<Record<string, unknown>>;
	source_url?: string;
	parent_event_id?: number;
	idempotency_key?: string;
	occurred_at?: string;
	behavior_source?: { behavior_id: number; window_id: number };
}

export type KnowledgeSaveInput =
	| (KnowledgeSaveBase & {
			payload_type?: "text" | "markdown";
			content: string;
	  })
	| (KnowledgeSaveBase & {
			payload_type: "json_template";
			payload_template: Record<string, unknown>;
			content?: string;
	  })
	| (KnowledgeSaveBase & {
			payload_type: "media" | "empty";
			content?: string;
	  });

export interface KnowledgeReadInput {
	/** Fetch specific content events by id. */
	content_ids?: number[];
	/** Fetch structured knowledge for a Behavior window. */
	behavior_id?: number;
	since?: string;
	until?: string;
	limit?: number;
	before_occurred_at?: string;
	before_id?: number;
	entity_ids?: number[];
}

export type KnowledgeDeleteInput =
	| number
	| { content_id?: number; content_ids?: number[]; reason?: string };

export interface KnowledgeNamespace {
	search(input: KnowledgeSearchInput): Promise<unknown>;
	save(input: KnowledgeSaveInput): Promise<unknown>;
	read(input: KnowledgeReadInput): Promise<unknown>;
	delete(input: KnowledgeDeleteInput): Promise<unknown>;
}

export function buildKnowledgeNamespace(
	ctx: ToolContext,
	env: Env,
): KnowledgeNamespace {
	return {
		search(input) {
			return search(input as never, env, ctx) as Promise<unknown>;
		},
		save(input) {
			return saveContent(input as never, env, ctx) as Promise<unknown>;
		},
		read(input) {
			return getContent(input as never, env, ctx) as Promise<unknown>;
		},
		delete(input) {
			const args =
				typeof input === "number" ? { content_id: input } : (input ?? {});
			return deleteContent(args as never, env, ctx) as Promise<unknown>;
		},
	};
}
		] = await Promise.all([
			import("../../../sandbox/namespaces/entities"),
			import("../../../sandbox/namespaces/feeds"),
			import("../../../sandbox/namespaces/classifiers"),
			import("../../../sandbox/namespaces/schedules"),
			import("../../../sandbox/namespaces/behaviors"),
			import("../../../sandbox/namespaces/entity-schema"),
			import("../../../sandbox/namespaces/connections"),
			import("../../../sandbox/namespaces/auth-profiles"),
			import("../../../sandbox/namespaces/agents"),
			import("../../../sandbox/namespaces/operations"),
			import("../../../sandbox/namespaces/notifications"),
		]);
		builders = {
			entities: entities.buildEntitiesNamespace,
			feeds: feeds.buildFeedsNamespace,
			classifiers: classifiers.buildClassifiersNamespace,
			schedules: schedules.buildSchedulesNamespace,
			behaviors: behaviors.buildBehaviorsNamespace,
			entitySchema: entitySchema.buildEntitySchemaNamespace,
			connections: connections.buildConnectionsNamespace,
			authProfiles: authProfiles.buildAuthProfilesNamespace,
			agents: agents.buildAgentsNamespace,
			operations: operations.buildOperationsNamespace,
			notifications: notifications.buildNotificationsNamespace,
		};
	});

	beforeEach(() => {
		calls.length = 0;
		behaviorGets.length = 0;
	});

	it("keeps knowledge.save content requirements aligned with payload_type", () => {
		const metadataOnly = {
			semantic_type: "valuation",
			payload_type: "empty",
			metadata: { amount: 42 },
		} satisfies KnowledgeSaveInput;
		const text = {
			semantic_type: "note",
			content: "hello",
		} satisfies KnowledgeSaveInput;
		// @ts-expect-error The omitted payload_type defaults to text at runtime.
		const missingDefaultText = { semantic_type: "note" } satisfies KnowledgeSaveInput;
		// @ts-expect-error Explicit text and markdown payloads require content.
		const missingExplicitText = { semantic_type: "note", payload_type: "text" } satisfies KnowledgeSaveInput;

		expect([
			metadataOnly,
